use vstd::prelude::*;

verus! {
    // Linear search: return the first index at which `target` appears in `nums`,
    // or -1 if it does not appear.  We assume nums.len() fits in a signed 32‐bit.
    fn linear_search(nums: Vec<i32>, target: i32) -> (ret: i32)
        requires
            // array length is strictly less than 2^31
            nums.len() <= std::i32::MAX as usize,
        ensures
            // If ret >= 0, it is a valid index, nums[ret] == target, and no earlier
            // element equals target.
            if ret >= 0 {
                let idx = ret as usize;
                idx < nums.len() &&
                nums[idx] == target &&
                forall |j: usize| j < idx ==> nums[j] != target
            }
            // If ret < 0, target does not occur anywhere in nums.
            else {
                forall |j: usize| j < nums.len() ==> nums[j] != target
            }
    {
        let len = nums.len();
        let mut i: usize = 0;
        // We scan from 0 up to len.  Loop invariant:
        //   1) 0 <= i <= len
        //   2) for all j < i, nums[j] != target
        // decreases len - i
        while i < len
            invariant
                i <= len,
                forall |j: usize| j < i ==> nums[j] != target,
            decreases
                len - i
        {
            if nums[i] == target {
                // safe to cast because i < len <= i32::MAX
                assert(i <= std::i32::MAX as usize);
                return i as i32;
            }
            i = i + 1;
        }
        // not found
        -1
    }
}

